-- Venue Live Guest "Grand Opening". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara grandopening), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'grandopening', 'Grand Opening (peresmian kantor / cabang)', 'grandopening', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 116, 'center 38%',
  $t${"name":"Grand Opening","orn":"diamond","ui":{"ivory":"#FBF8F3","white":"#FFFFFF","soft":"#EDE4F5","soft2":"#CDB8E3","accent":"#5B2A86","deep":"#3A1A57","ink":"#241036","mute":"#7A6B8C","line":"#DDD0EA","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#FFFCF8","ink":"#241036","accent":"#5B2A86","gold":"#C9A227","leaf":"#EDE4F5","hbg":"rgba(251,248,243,.94)","hline":"#CDB8E3","motif":"diamond"},"hud":{"bg":"rgba(58,26,87,.84)","acc":"#F2D98A","on":"#241036"},"scr":{"wine":"#3A1A57","veil":"251,248,243"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'grandopening');
update public.live_venues set decor = $d${"speakers":{"url":"/assets/live-decor/grandopening/speakers.webp","w":2.4},"rope":{"url":"/assets/live-decor/grandopening/rope.webp","w":6,"x":0,"z":-1},"stall_snacks":{"url":"/assets/live-decor/grandopening/stall_snacks.webp","w":3.0},"stall_candy":{"url":"/assets/live-decor/grandopening/stall_candy.webp","w":2.8},"stall_drinks":{"url":"/assets/live-decor/grandopening/stall_drinks.webp","w":4.8},"photobooth":{"url":"/assets/live-decor/grandopening/photobooth.webp","w":5.6},"claw":{"url":"/assets/live-decor/grandopening/claw.webp","w":4.4},"arch":{"url":"/assets/live-decor/grandopening/arch.webp","w":12,"x":0,"z":-27},"fountain":{"url":"/assets/live-decor/grandopening/fountain.webp","w":5.8},"sign":{"url":"/assets/live-decor/grandopening/sign.webp","w":1.2},"easel":{"url":"/assets/live-decor/grandopening/easel.webp","w":2.8,"x":4.6,"z":8.2},"table":{"url":"/assets/live-decor/grandopening/table.webp"},"banner":{"url":"/assets/live-decor/grandopening/banner.webp","w":1.6},"gifts":{"url":"/assets/live-decor/grandopening/gifts.webp","w":2.2},"av_host":{"url":"/assets/live-decor/grandopening/av_host.webp","name":"Direktur Jas Ungu"},"av_l1":{"url":"/assets/live-decor/grandopening/av_l1.webp","name":"Direktur Jas Ungu"},"av_l2":{"url":"/assets/live-decor/grandopening/av_l2.webp","name":"Staf Batik Kacamata"},"av_l3":{"url":"/assets/live-decor/grandopening/av_l3.webp","name":"Staf Rompi Ungu"},"av_l4":{"url":"/assets/live-decor/grandopening/av_l4.webp","name":"Tamu Blazer Krem"},"av_p1":{"url":"/assets/live-decor/grandopening/av_p1.webp","name":"Manajer Hijab Ungu"},"av_p2":{"url":"/assets/live-decor/grandopening/av_p2.webp","name":"Manajer Blazer Krem"},"av_p3":{"url":"/assets/live-decor/grandopening/av_p3.webp","name":"Tamu Gaun Lilac"}}$d$::jsonb, background_url = '/assets/live-decor/grandopening/painting.webp', active = true, updated_at = now() where key = 'grandopening';
